Implementing automatic token refresh in your current setup can significantly enhance the user experience by ensuring that tokens are always valid without requiring manual intervention. Here's a step-by-step guide to help you implement automatic token refresh using FastAPI and Redis for caching tokens:

### Step-by-Step Guide

1. **Generate Access and Refresh Tokens:**
   - When a user logs in, generate both an access token and a refresh token.
   - Store the refresh token securely in your database or another secure storage.

2. **Validate Access Tokens:**
   - Validate the access token on each request.
   - If the access token is close to expiring, use the refresh token to obtain a new access token.

3. **Handle Token Refresh:**
   - Implement a mechanism to automatically refresh the access token when it is close to expiring.

### Example Implementation

#### 1. Token Generation

Generate both access and refresh tokens during login:

```python
import jwt
from datetime import datetime, timedelta
from fastapi import FastAPI, Depends, HTTPException
from fastapi.security import OAuth2PasswordBearer
from pydantic import BaseModel
import redis

app = FastAPI()

oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")

SECRET_KEY = "your_secret_key"
ALGORITHM = "HS256"
ACCESS_TOKEN_EXPIRE_MINUTES = 30
REFRESH_TOKEN_EXPIRE_HOURS = 24

r = redis.Redis(host='localhost', port=6379, db=0, decode_responses=True)

def create_access_token(data: dict, expires_delta: timedelta = None):
    to_encode = data.copy()
    if expires_delta:
        expire = datetime.utcnow() + expires_delta
    else:
        expire = datetime.utcnow() + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    to_encode.update({"exp": expire})
    encoded_jwt = jwt.encode(to_encode, SECRET_KEY, algorithm=ALGORITHM)
    return encoded_jwt

def create_refresh_token(data: dict, expires_delta: timedelta = None):
    to_encode = data.copy()
    if expires_delta:
        expire = datetime.utcnow() + expires_delta
    else:
        expire = datetime.utcnow() + timedelta(hours=REFRESH_TOKEN_EXPIRE_HOURS)
    to_encode.update({"exp": expire})
    encoded_jwt = jwt.encode(to_encode, SECRET_KEY, algorithm=ALGORITHM)
    return encoded_jwt

@app.post("/token")
async def login(username: str, password: str):
    user = authenticate_user(username, password)
    if not user:
        raise HTTPException(status_code=400, detail="Incorrect username or password")
    access_token = create_access_token({"sub": user.username})
    refresh_token = create_refresh_token({"sub": user.username})
    r.set(f"refresh:{user.username}", refresh_token, ex=timedelta(hours=REFRESH_TOKEN_EXPIRE_HOURS))
    return {"access_token": access_token, "refresh_token": refresh_token, "token_type": "bearer"}
```

#### 2. Token Validation and Refresh

Validate the access token and automatically refresh it if it is close to expiring:

```python
def validate_token(token: str):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        if datetime.utcnow() >= payload['exp']:
            raise HTTPException(status_code=401, detail="Token has expired")
        return payload
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token has expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")

def refresh_access_token(refresh_token: str, username: str):
    try:
        payload = jwt.decode(refresh_token, SECRET_KEY, algorithms=[ALGORITHM])
        if payload['sub'] != username:
            raise HTTPException(status_code=401, detail="Invalid refresh token")
        return create_access_token({"sub": username})
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Refresh token has expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid refresh token")

@app.get("/api/v1/start")
async def start(token: str = Depends(oauth2_scheme)):
    try:
        payload = validate_token(token)
        username = payload['sub']
        if datetime.utcnow() + timedelta(minutes=5) >= payload['exp']:
            # Token is close to expiring, refresh it
            refresh_token = r.get(f"refresh:{username}")
            if not refresh_token:
                raise HTTPException(status_code=401, detail="Refresh token not found")
            new_access_token = refresh_access_token(refresh_token, username)
            return {"access_token": new_access_token, "token_type": "bearer"}
        return {"message": "Start command executed successfully"}
    except HTTPException as e:
        raise e
```

#### 3. Handle Token Refresh in Frontend

Ensure your frontend handles the automatic token refresh:

```javascript
// Example frontend logic using Axios
axios.interceptors.response.use(
    response => response,
    error => {
        if (error.response.status === 401) {
            const refreshToken = localStorage.getItem('refresh_token');
            if (refreshToken) {
                axios.post('/refresh', { refresh_token: refreshToken })
                    .then(response => {
                        localStorage.setItem('access_token', response.data.access_token);
                        axios.defaults.headers.common['Authorization'] = `Bearer ${response.data.access_token}`;
                        return axios(error.config);
                    })
                    .catch(err => {
                        console.error('Failed to refresh token:', err);
                        // Handle logout or other actions
                    });
            }
        }
        return Promise.reject(error);
    }
);

axios.post('/token', {
    username: 'user',
    password: 'password'
}).then(response => {
    localStorage.setItem('access_token', response.data.access_token);
    localStorage.setItem('refresh_token', response.data.refresh_token);
    axios.defaults.headers.common['Authorization'] = `Bearer ${response.data.access_token}`;
});
```

### Summary

By following these steps, you can implement automatic token refresh in your FastAPI application. This ensures that tokens are always valid and enhances the user experience. Ensure that your token generation and validation logic are consistent and robust, and use detailed logging and metrics to track and diagnose issues. If you have any further questions or need additional guidance, feel free to ask!

