{
  "name": "High Number of Agent Failures",
  "consumer_group": "observability",
  "rule_type_id": "siem.query",
  "enabled": true,
  "schedule": {
    "interval": "1m"
  },
  "inputs": [
    {
      "type": "search",
      "index": ["agent_interactions-*"],
      "query": {
        "bool": {
          "must": [
            {
              "range": {
                "timestamp": {
                  "gte": "now-1m",
                  "lt": "now"
                }
              }
            }
          ]
        }
      },
      "aggregations": {
        "total_failures": {
          "value_count": {
            "field": "agent_id"
          }
        }
      }
    }
  ],
