        stage('Build') {
            steps {
                script {
                    // Build the agent services
                    echo "Building agent services..."
                    sh "cd ${BUILD_DIR} && make build"
                }
            }
        }

        stage('Test') {
            parallel {
                stage('Unit Tests') {
                    steps {
                        script {
                            // Run unit tests
                            echo "Running unit tests..."
                            sh "cd ${TEST_DIR} && make unit-tests"
                        }
                    }
                }
                stage('Integration Tests') {
                    steps {
                        script {
                            // Run integration tests
                            echo "Running integration tests..."
                            sh "cd ${TEST_DIR} && make integration-tests"
                        }
                    }
                }
            }
        }

        stage('Deploy') {
            steps {
                script {
                    // Deploy the agent services
                    echo "Deploying agent services..."
                    sh "cd ${DEPLOY_DIR} && make deploy"
                }
            }
        }
