    post {
        always {
            // Clean up workspace
            cleanWs()
        }
        success {
            // Notify success
            echo "Pipeline succeeded!"
        }
        failure {
            // Notify failure
            echo "Pipeline failed!"
            // Optionally, you can add steps to send notifications or emails
