        stage('Deploy') {
            steps {
                script {
                    echo "Deploying with ${AGENTS_PER_SERVICE} agents"
                    sh "make deploy"
                }
                // Use the Jenkins Deploy Plugin to deploy the artifact
                deploy adapters: [[$class: 'ArtifactDeploymentAdapter', artifactPattern: '**/target/*.war', deployTo: 'your-deployment-target']],
                      credentialsId: 'your-credentials-id',
                      serverUrl: 'http://your-deployment-server-url'
            }
        }
    }

    post {
        always {
            // Clean up workspace
            cleanWs()
        }
        success {
            // Notify success
            echo "Pipeline succeeded!"
        }
        failure {
            // Notify failure
            echo "Pipeline failed!"
            // Optionally, you can add steps to send notifications or emails
            // mail to: 'team@example.com', subject: 'Jenkins Pipeline Failed', body: 'The pipeline failed.'
        }
    }
}
