```groovy
pipeline {
    agent any

    environment {
        GIT_CREDENTIALS_ID = 'your-github-credentials-id'
        EMAIL_RECIPIENTS = 'team@example.com'
    }

    stages {
        stage('Checkout') {
            steps {
                checkout([
                    $class: 'GitSCM',
                    branches: [[name: '*/develop']],
                    doGenerateSubmoduleConfigurations: false,
                    extensions: [],
                    submoduleCfg: [],
                    userRemoteConfigs: [
