            // Check if the record already exists
            PreparedStatement checkStmt = conn.prepareStatement("SELECT * FROM mytable WHERE key = ?");
            checkStmt.setString(1, key);
            ResultSet rs = checkStmt.executeQuery();

            if (rs.next()) {
                // Record exists, update it
                PreparedStatement updateStmt = conn.prepareStatement("UPDATE mytable SET value = ? WHERE key = ?");
                updateStmt.setString(1, value);
                updateStmt.setString(2, key);
                updateStmt.executeUpdate();
                System.out.println("Record updated: " + key);
            } else {
                // Record does not exist, insert it
                PreparedStatement insertStmt = conn.prepareStatement("INSERT INTO mytable (key, value) VALUES (?, ?)");
                insertStmt.setString(1, key);
                insertStmt.setString(2, value);
