            steps {
                checkout scm
            }
        }

        stage('Setup Environment') {
            steps {
                script {
                    // Create cache directory
                    sh "mkdir -p ${CACHE_DIR}"

                    // Cache pip dependencies
                    cache(path: "${CACHE_DIR}", key: 'pip-dependencies-${BUILD_ID}') {
                        sh "pip install --upgrade pip"
                        sh "pip install --cache-dir ${CACHE_DIR} -r requirements.txt"
                    }
                }
            }
