```python
import requests
import time
from concurrent.futures import ThreadPoolExecutor, as_completed

def send_request(url):
    try:
        response = requests.get(url)
        if response.status_code != 200:
            print(f"Request failed with status code {response.status_code}")
        return response.status_code
    except Exception as e:
        print(f"Request failed with exception: {e}")
        return None

def simulate_traffic(url, num_requests, request_interval):
    start_time = time.time()
    successes = 0
    failures = 0

    with ThreadPoolExecutor(max_workers=num_requests) as executor:
        futures = [executor.submit(send_request, url) for _ in range(num_requests)]

        for future in as_completed(futures):
            if future.result() == 200:
                successes += 1
            else:
                failures += 1

    end_time = time.time()
    total_time = end_time - start_time
    print(f"Total time: {total_time:.2f} seconds")
    print(f"Successes: {successes}, Failures: {failures}")

url = "http://localhost:8080/api/v1/build"
num_requests = 500
request_interval = 0.002  # 2ms interval to simulate 500 requests per second

simulate_traffic(url, num_requests, request_interval)
```

