    agent any

    environment {
        MAX_RETRIES = 3
        RETRY_INTERVAL = 30
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }

        stage('Build') {
            steps {
                script {
                    def maxRetries = env.MAX_RETRIES.toInteger()
                    def retryInterval = env.RETRY_INTERVAL.toInteger()
                    def retries = 0

                    while (retries < maxRetries) {
                        try {
                            // Your build steps here
                            sh 'make build'
                            echo "Build succeeded."
                            break
                        } catch (Exception e) {
                            retries++
                            if (retries < maxRetries) {
                                echo "Build failed with error ${e.message}. Retrying in ${retryInterval} seconds..."
                                sleep time: retryInterval
                            } else {
                                echo "Build failed with error ${e.message} after ${maxRetries} retries."
                                throw e
                            }
                        }
                    }
                }
            }
        }

        stage('Test') {
            steps {
                script {
