Here's how you can implement React Query to optimize your data fetching and reduce lag:

```jsx
import React from 'react';
import { useQuery, useQueryClient } from 'react-query';

const fetchAgentMetrics = async () => {
  const response = await fetch('/api/agent-metrics');
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  return response.json();
};

const AgentMetrics = () => {
  const queryClient = useQueryClient();
  const { data, error, isLoading } = useQuery(
    'agentMetrics',
    fetchAgentMetrics,
    {
      staleTime: 5000, // Data is considered fresh for 5 seconds
      retry: 3, // Retry up to 3 times on failure
      refetchOnWindowFocus: false, // Disable refetching on window focus
      refetchInterval: 10000, // Refetch every 10 seconds
    }
  );

  if (isLoading) return <div>Loading...</div>;
  if (error) return <div>Error: {error.message}</div>;

  return (
    <div>
      {data.map((metric) => (
        <div key={metric.agentId}>
          <span>{metric.agentName}</span>
          <span>{metric.metricValue}</span>
        </div>
      ))}
    </div>
  );
};

export default AgentMetrics;
