   ```

2. **Set Up Query Client**:
   Create a query client and provide it to your application using the `QueryClientProvider`.

   ```jsx
   import React from 'react';
   import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

   const queryClient = new QueryClient();

   function App() {
     return (
       <QueryClientProvider client={queryClient}>
         <AgentList />
       </QueryClientProvider>
     );
   }

   export default App;
   ```

3. **Fetch Agents Data**:
   Use the `useQuery` hook to fetch and cache the agents data.

   ```jsx
   import React from 'react';
   import { useQuery } from '@tanstack/react-query';

   const fetchAgents = async () => {
     const response = await fetch('/api/agents');
     if (!response.ok) {
       throw new Error(`HTTP error! status: ${response.status}`);
     }
     return response.json();
   };

   function AgentList() {
     const { data, isLoading, isError } = useQuery(['agents'], fetchAgents, {
       staleTime: 1000 * 60 * 5, // Cache data for 5 minutes
       refetchOnWindowFocus: false, // Disable refetching on window focus
       keepPreviousData: true, // Keep previous data while fetching new data
     });

     if (isLoading) return <div>Loading...</div>;
     if (isError) return <div>Error occurred.</div>;

     return (
       <div>
         {data?.agents.map(agent => (
           <AgentCard key={agent.id} agent={agent} />
         ))}
       </div>
     );
   }

   export default AgentList;
   ```

4. **Define Agent Card Component**:
   Create the `AgentCard` component to display individual agent data.

   ```jsx
   import React from 'react';

   function AgentCard({ agent }) {
     if (!agent) {
       return null; // Return null if agent is undefined or null
     }

     const name = agent.name || 'Unknown';
     const description = agent.description || 'No description provided';

     return (
       <div>
         <h2>{name}</h2>
         <p>{description}</p>
       </div>
     );
   }

   export default AgentCard;
   ```

5. **Handle Cache Invalidation**:
   To invalidate the cache and refetch data, you can use the `refetch` method provided by the `useQuery` hook.

   ```jsx
   import React from 'react';
   import { useQuery } from '@tanstack/react-query';

   function AgentList() {
     const { data, isLoading, isError, refetch } = useQuery(['agents'], fetchAgents, {
       staleTime: 1000 * 60 * 5, // Cache data for  5 minutes
       refetchOnWindowFocus: false, // Disable refetching on window focus
       keepPreviousData: true, // Keep previous data while fetching new data
     });

     if (isLoading) return <div>Loading...</div>;
     if (isError) return <div>Error occurred.</div>;

     return (
       <div>
         {data?.agents.map(agent => (
           <AgentCard key={agent.id} agent={agent} />
         ))}
         <button onClick={() => refetch()}>Refresh Data</button>
       </div>
     );
   }

   export default AgentList;
   ```

