### Example Code

Here's how you can implement this:

```jsx
import React from 'react';

function AgentCard({ agent }) {
  if (!agent) {
    return null; // Return null if agent is undefined or null
  }

  const name = getPropValue(agent, ['name', 'fullName']);
  const description = getPropValue(agent, ['description', 'details']);

  return (
    <div>
      <h2>{name}</h2>
      <p>{description}</p>
    </div>
  );
}

function getPropValue(obj, keys) {
