    try {
      const response = await axios.get('/api/agents');
      setData(response.data);
      setLoading(false);
    } catch (err) {
      if (retryCount < 3) {
        // Exponential backoff
        const delay = Math.pow(2, retryCount) * 1000;
        setTimeout(() => fetchAgents(retryCount + 1), delay);
      } else {
