  const { isAuthenticated, getAccessTokenSilently } = useAuth0();
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [selectedRoles, setSelectedRoles] = useState([]);

  useEffect(() => {
    if (isAuthenticated) {
      fetchUsers();
    }
  }, [isAuthenticated]);

  const fetchUsers = async () => {
    const token = await getAccessTokenSilently();
    const response = await auth0Client.users.getAllUsers({
      audience: 'https://yourdomain.com/api/v2/',
      token,
    });
    setUsers(response);
  };

  const assignRoles = async () => {
    if (selectedUser && selectedRoles.length > 0) {
      const token = await getAccessTokenSilently();
      await auth0Client.users.updateUserRoles({
        userId: selectedUser.user_id,
        roles: selectedRoles,
        audience: 'https://yourdomain.com/api/v2/',
        token,
      });
      alert('Roles assigned successfully!');
    }
  };

  return (
    <div>
      <h2>Role Management</h2>
      <select
        value={selectedUser?.email || ''}
        onChange={(e) => {
          const user = users.find((u) => u.email === e.target.value);
          setSelectedUser(user);
        }}
      >
        <option value="">Select a user</option>
        {users.map((user) => (
          <option key={user.user_id} value={user.email}>
            {user.email}
          </option>
        ))}
      </select>
      <br />
      <br />
      <select
        multiple
        value={selectedRoles}
        onChange={(e) => setSelectedRoles(Array.from(e.target.selectedOptions, (option) => option.value))}
      >
        <option value="admin">Admin</option>
        <option value="editor">Editor</option>
        <option value="viewer">Viewer</option>
      </select>
      <br />
      <br />
      <button onClick={assignRoles}>Assign Roles</button>
    </div>
  );
}

export default RoleManagement;
```

#### 2. Create an Auth0 Management Client

