import { createAuth0Client } from '@auth0/auth0-client';

const auth0Client = createAuth0Client({
  domain: 'YOUR_AUTH0_DOMAIN.auth0.com',
  client_id: 'YOUR_MACHINE_USER_CLIENT_ID',
  client_secret: 'YOUR_MACHINE_USER_CLIENT_SECRET',
});

export default auth0Client;
```

#### 3. Update `App` Component to Include Role Management

```jsx
import React from 'react';
import { BrowserRouter as Router, Route, Redirect, Switch } from 'react-router-dom';
import { Auth0Provider, useAuth0 } from '@auth0/auth0-react';
import Dashboard from './components/Dashboard';
import AdminDashboard from './components/AdminDashboard';
import Login from './components/Login';
import RoleManagement from './components/RoleManagement';
import auth0Config from './auth0-config';

function App() {
  return (
    <Auth0Provider
      domain={auth0Config.AUTH0_DOMAIN}
      clientId={auth0Config.AUTH0_CLIENT_ID}
      redirectUri={window.location.origin + '/callback'}
    >
      <Router>
        <Switch>
          <Route path="/dashboard">
            <ProtectedRoute component={Dashboard} />
          </Route>
          <Route path="/admin-dashboard">
            <AdminProtectedRoute component={AdminDashboard} />
          </_Route>
          <Route path="/role-management">
            <AdminProtectedRoute component={RoleManagement} />
          </Route>
          <Route path="/login">
            <Login />
          </Route>
          <Route path="/callback">
            <Callback />
          </Route>
          <Redirect to="/login" />
        </Switch>
      </Router>
    </Auth0Provider>
  );
}

function ProtectedRoute({ component: Component, ...rest }) {
  const { isAuthenticated } = useAuth0();

  return (
    <Route
      {...rest}
      render={(props) =>
        isAuthenticated ? (
          <Component {...props} />
        ) : (
          <Redirect to="/login" />
        )
      }
    />
  );
}

function AdminProtectedRoute({ component: Component, ...rest }) {
  const { isAuthenticated, getAccessTokenSilently, getIdTokenClaims } = useAuth0();

  useEffect(() => {
    const checkRole = async () => {
      try {
        const token = await getAccessTokenSilently();
        const claims = await getIdTokenClaims(token);
        const roles = claims[auth0Config.AUTH0_ROLES_CLAIM];
        if (!roles.includes('admin')) {
          props.history.push('/dashboard');
        }
      } catch (error) {
        console.error('Error checking role:', error);
      }
    };

    if (isAuthenticated) {
      checkRole();
    }
  }, [isAuthenticated, getAccessTokenSilently, getIdTokenClaims, props.history]);

  return (
    <Route
      {...rest}
      render={(props) =>
        isAuthenticated ? (
          <Component {...props} />
        ) : (
          <Redirect to="/login" />
        )
      }
    />
  );
}

function Callback() {
  const { loginWithRedirect, isLoading } = useAuth0();

  useEffect(() => {
    if (!isLoading) {
      loginWithRedirect();
    }
  }, [isLoading, loginWithRedirect]);

  return <div>Loading...</div>;
}

export default App;
```

### Explanation

1. **Auth0 Management Client**:
   - The `auth0-management-client.js` file initializes an Auth0 client with the machine user credentials to interact with the Auth0 management API.

2. **RoleManagement Component**:
   - Fetches users from Auth0 and allows administrators to select a user and assign roles.
   - Uses the Auth0 management API to update user roles.

3. **ProtectedRoute and AdminProtectedRoute**:
   - Ensure that only authenticated users can access the dashboard and only users with the `admin` role can access the role management interface.

By following these steps, you can implement role assignment and management within your React application using Auth0. This setup allows administrators to manage user roles and permissions directly from the application. If you have any specific issues or need further assistance, feel free to ask!

